/**
 * Model User
 * Tabla de usuarios del sistema.
 * Se puede buscar tanto por `username` como por `codigo` (ambos únicos).
 */
export type User = $Result.DefaultSelection<Prisma.$UserPayload>
/**
 * Model Course
 * Representa un curso o grupo académico.
 * Un curso tiene un código, un nombre, un periodo y un grupo.
 */
export type Course = $Result.DefaultSelection<Prisma.$CoursePayload>
/**
 * Model CourseStudent
 * Relación N:M entre usuarios y cursos (como estudiantes)
 */
export type CourseStudent = $Result.DefaultSelection<Prisma.$CourseStudentPayload>
/**
 * Model Challenge
 * Reto algorítmico asociado a un curso.
 * Incluye su dificultad, límites y estado (borrador, publicado o archivado).
 */
export type Challenge = $Result.DefaultSelection<Prisma.$ChallengePayload>
/**
 * Model Testcase
 * Caso de prueba de un reto (input y output esperados).
 * Algunos casos pueden ser ocultos (visible = false) para los estudiantes.
 */
export type Testcase = $Result.DefaultSelection<Prisma.$TestcasePayload>
/**
 * Model Submission
 * Envío (submission) de un estudiante para un reto.
 * Guarda el código, lenguaje, estado y puntaje final.
 */
export type Submission = $Result.DefaultSelection<Prisma.$SubmissionPayload>
/**
 * Model Evaluation
 * 
 */
export type Evaluation = $Result.DefaultSelection<Prisma.$EvaluationPayload>
/**
 * Model EvaluationChallenge
 * 
 */
export type EvaluationChallenge = $Result.DefaultSelection<Prisma.$EvaluationChallengePayload>
/**
 * Model SubmissionTestResult
 * Resultado individual de cada caso de prueba ejecutado en un submission.
 * Almacena el estado, tiempo de ejecución y salida de cada test case.
 */
export type SubmissionTestResult = $Result.DefaultSelection<Prisma.$SubmissionTestResultPayload>
/**
 * Model Lesson
 * Lección dentro de un curso (contenido de aprendizaje)
 */
export type Lesson = $Result.DefaultSelection<Prisma.$LessonPayload>
/**
 * Model LessonResource
 * Recurso asociado a una lección (PDFs, links, código, etc.)
 */
export type LessonResource = $Result.DefaultSelection<Prisma.$LessonResourcePayload>

